    /// thread would race with.
    ///
    /// ```compile_fail,E0277
    /// use libgit2_crustify::git2::src::cli::opt::Spec;
    /// use ffibox::CZeroable;
    ///
    /// let spec: Spec<'static> = Spec::zeroed();
