    assert_eq!(spec.kind(), None);
    assert!(spec.target().is_none());

    let raw = sys::cli_opt {
        status: sys::CLI_OPT_STATUS_MISSING_ARGUMENT + 1,
        ..Default::default()
    };
    // SAFETY: `raw` is a live outcome with `NULL` pointers, borrowed for the handle.
