            (_, spec) => spec,
        };
        if let Some(command) = command {
            out.write_all(&[command.as_bytes(), b": "].concat())?;
        }
        match (status, named) {
            (Some(Status::Done), _) => out.write_all(b"finished processing arguments (no error)\n"),
            (Some(Status::Ok), _) => out.write_all(b"no error\n"),
            (Some(Status::UnknownOption), _) => {
                out.write_all(&[b"unknown option: ", c_text(self.arg()), b"\n"].concat())
