            }
        }
    }
}

/// Writes the requirement of the choice that starts at `first` of `specs`, which
/// [`spec_is_choice`]: `either` its two options, or `one of` its three or more, each named, and
/// `is required.`.
fn write_choices<W: io::Write + ?Sized>(
    out: &mut W,
    specs: SpecTable<'_>,
    first: usize,
) -> io::Result<()> {
    let lead: &[u8] = if spec_is_choice(specs, first + 1) {
        b"one of"
    } else {
        b"either"
    };
    out.write_all(lead)?;
    let mut index = first;
    while let Some(choice) = specs.get(index) {
        let more = spec_is_choice(specs, index);
        if !more {
            out.write_all(b" or")?;
        } else if index != first {
            out.write_all(b",")?;
        }
        out.write_all(b" '")?;
        write_spec_name(out, choice)?;
        out.write_all(b"'")?;
        if !more {
            break;
        }
        index += 1;
    }
    out.write_all(b" is required.\n")
}

