                Target::None | Target::Literal => ptr::null_mut(),
                Target::Bool(v) | Target::Switch(v) | Target::Accumulator(v) => erase(v),
                Target::Value(v) | Target::Arg(v) => erase(v),
                Target::Args(v) => erase(v),
