fn check_required<'p>(
    specs: SpecTable<'p>,
    given: &[SpecRef<'_, 'p>],
) -> Result<(), SpecRef<'p, 'p>> {
    let mut required = None;
    let mut met = false;
    for (index, spec) in specs.iter().enumerate() {
        let head = match required {
            Some(head) => head,
            None if spec.usage().contains(Usage::REQUIRED) => {
                met = false;
                spec
            }
            None => continue,
        };
        required = Some(head);
        met = met || is_given(given, spec);
        if !is_choice(specs, index) {
            if !met {
                return Err(head);
            }
            required = None;
            met = false;
        }
    }
    Ok(())
}

