        fn c_first<'p>(table: SpecTable<'p>, args: &'p mut [Arg<'p>]) -> (Opt<'p>, Parser<'p>) {
            let mut parser = Parser::new(table, args, ParseFlags::DEFAULT);
            let mut opt = Opt::zeroed();
            c_next(&mut opt, &mut parser);
            (opt, parser)
        }

