            let cases: [&[&CStr]; 6] = [
                &[c"-a", c"file"],
                &[c"--bee", c"file"],
                &[c"-c", c"file"],
                &[c"-vx", c"file"],
                &[c"file", c"-a", c"more"],
                &[c"-a", c"-c", c"file", c"rest"],
