        #[test]
        #[cfg_attr(miri, ignore = "calls C")]
        fn the_requirement_c_reports_missing_is_the_one_rust_reports() {
            let specs = [
                Spec::new(Target::Switch(None)).with_alias(b'x'),
                Spec::new(Target::Value(None)).with_alias(b'n').with_usage(Usage::REQUIRED),
                Spec::new(Target::Switch(None)).with_alias(b'a').with_usage(Usage::REQUIRED),
                Spec::new(Target::Switch(None)).with_alias(b'b').with_usage(Usage::CHOICE),
                Spec::new(Target::Switch(None))
                    .with_alias(b'c')
                    .with_usage(Usage::CHOICE | Usage::REQUIRED),
                Spec::new(Target::Switch(None)).with_alias(b'd'),
                Spec::new(Target::Switch(None)).with_alias(b'e').with_usage(Usage::CHOICE),
                Spec::new(Target::Switch(None)).with_alias(b'f').with_usage(Usage::REQUIRED),
                Spec::new(Target::Switch(None)).with_alias(b'g').with_usage(Usage::CHOICE),
                Spec::default(),
