def move_into_loop(s, fn_name, loop_head):
    i=s.index("fn "+fn_name+"(")
    body_start=s.index("{\n",i)+2
    j=s.index(loop_head,body_start)
    pre=s[body_start:j]
    # split pre into specs part (from 'let specs' or cells through 'let table = ...;') and others
    m=re.search(r"( *let (?:\(debug, x\)|specs).*?let table = SpecTable::new\(&specs\)\.unwrap\(\);\n)", pre, re.S)
    assert m, fn_name
    specs_part=m.group(1)
    rest=pre.replace(specs_part,"")
    # indent specs part by 4
    specs_in="".join(("    "+l if l.strip() else l) for l in specs_part.splitlines(True))
    head_end=s.index("\n",j)+1
    return s[:body_start]+rest+s[j:head_end]+specs_in+s[head_end:]

