    fail_at: usize,
}

impl io::Write for Pieces {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        if self.pieces.len() == self.fail_at {
            return Err(io::Error::from(io::ErrorKind::BrokenPipe));
        }
        self.pieces.push(buf.to_vec());
        Ok(buf.len())
    }

