fn the_message_is_written_in_c_pieces_until_one_fails() {
    let specs = [
        Spec::new(Target::Switch(None)).with_alias(b'a'),
        Spec::new(Target::Switch(None)).with_alias(b'b').with_usage(Usage::CHOICE),
        Spec::zeroed(),
    ];
    let table = SpecTable::new(&specs).expect("ended");
    let opt = outcome(Status::MissingArgument, Some(0), None, table);
    let all: [&[u8]; 11] =
        [b"git2: ", b"either", b" '", b"-a", b"'", b" or", b" '", b"-b", b"'", b" is required.\\n", b""];
    let mut out = Pieces { pieces: Vec::new(), fail_at: usize::MAX };
    opt.as_ref().write_status(&mut out, Some("git2"), table).unwrap();
    assert_eq!(out.pieces, all[..10]);
    for fail_at in 0..10 {
        let mut out = Pieces { pieces: Vec::new(), fail_at };
        let e = opt.as_ref().write_status(&mut out, Some("git2"), table).unwrap_err();
        assert_eq!(e.kind(), io::ErrorKind::BrokenPipe);
        assert_eq!(out.pieces, all[..fail_at], "{fail_at}");
    }
    let opt = outcome(Status::MissingValue, Some(1), None, table);
    let mut out = Pieces { pieces: Vec::new(), fail_at: usize::MAX };
    opt.as_ref().write_status(&mut out, None, table).unwrap();
